/* ===== W-2/W-3: 移动端顶栏 + 抽屉化侧栏 + 硬件菜单键 ===== */

/* 顶栏: 仅 ≤640px 可见, 桌面端隐藏 */
#topbar{display:none;align-items:center;gap:var(--space-1);padding:var(--space-1-5) var(--space-3);
    border-bottom:var(--p-hairline) solid var(--color-line);background:var(--color-sidebar-bg);
    flex:none;height:44px}
#topbar-title{flex:1;font-size:var(--text-sm);font-weight:var(--weight-medium);color:var(--color-text);
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-family:var(--font-ui);
    margin:0 var(--space-2)}
.topbar-acts{display:flex;align-items:center;gap:0}
.topbar-acts .tb-btn{background:transparent;border:none;border-radius:var(--radius-md);
    padding:var(--space-1-5);color:var(--color-text-muted);cursor:pointer;
    display:inline-flex;align-items:center;justify-content:center;
    transition:background var(--duration-base) var(--ease-out),color var(--duration-base) var(--ease-out)}
.topbar-acts .tb-btn:hover{background:var(--color-hover);color:var(--color-text)}
.topbar-acts .tb-btn svg{flex:none}

/* 抽屉遮罩: 点击关闭侧栏 */
#nav-scrim{display:none;position:fixed;inset:0;background:var(--color-scrim-strong);
    z-index:var(--z-modal);pointer-events:none;opacity:0;
    transition:opacity var(--duration-base) var(--ease-out)}
body.nav-open #nav-scrim{opacity:1;pointer-events:auto}

/* ≤640px: 侧栏变为抽屉, 顶栏可见 */
@media (max-width:640px){
    #topbar{display:flex}
    #sidebar{position:fixed;top:0;left:0;bottom:0;
        width:var(--p-sidebar-w);min-width:var(--p-sidebar-w);
        z-index:calc(var(--z-modal) + 1);
        transform:translateX(-100%);
        transition:transform var(--duration-base) var(--ease-out);
        box-shadow:var(--shadow-lg)}
    body.nav-open #sidebar{transform:translateX(0)}
    /* 恢复被原有规则隐藏的文字标签 */
    .brand .tuan,#searchbox,.ws-label,#ws-name,
    #newbtn{justify-content:flex-start;padding:var(--space-2) var(--space-3)}
    #newbtn .lbl{display:inline}
    #sidebar .foot{flex-direction:row;align-items:center;gap:var(--space-1)}
    #sidefoot{display:block}
    /* 顶栏已提供快捷入口, 抽屉内不重复 */
    #btn-theme,#btn-panel,#btn-settings{display:none}
    /* 抽屉排他: 侧栏打开时右面板收起 */
    body.nav-open #rpanel.open{width:0;min-width:0;overflow:hidden}
    #rpanel.open{position:absolute;right:0;top:0;bottom:0;z-index:var(--z-modal);width:86vw;min-width:86vw}
    #inp{font-size:16px}
    #msgs{padding-top:var(--space-3)}
}
</style>

