/* ===== W-2/W-3: 导航桥接 + 硬件菜单键 + 小屏抽屉 + 顶栏互斥 ===== */
/* 命名空间: 原生壳拦 KEYCODE_MENU 后调 window.__nav.toggleSidebar() */
window.__nav=window.__nav||{};

/* 抽屉开关: 切换 body.nav-open 类, 打开时排他关闭右面板 */
function _navToggleDrawer(force){
  var body=document.body;
  var open=(typeof force==='boolean')?force:!body.classList.contains('nav-open');
  body.classList.toggle('nav-open',open);
  if(open){
    var rp=document.getElementById('rpanel');
    if(rp&&rp.classList.contains('open'))rp.classList.remove('open');
  }
}

window.__nav.toggleSidebar=function(force){_navToggleDrawer(force);};

window.__nav.togglePanel=function(force){
  var rp=document.getElementById('rpanel');
  if(rp){
    var willOpen=(typeof force==='boolean')?force:!rp.classList.contains('open');
    if(willOpen)document.body.classList.remove('nav-open');
  }
  togglePanel(force);
};

/* 顶栏标题: 显示当前会话名或默认 TUAN */
function updateTopbarTitle(){
  var el=document.getElementById('topbar-title');if(!el)return;
  if(current){
    var s=allSessions.find(function(x){return x.id===current;});
    el.textContent=(s&&s.title)?s.title:'TUAN';
  }else{
    el.textContent='TUAN';
  }
}

/* 硬件菜单键: Android WebView 派发 e.key === 'ContextMenu' */
document.addEventListener('keydown',function(e){
  if(e.key==='ContextMenu'){e.preventDefault();_navToggleDrawer();}
  /* Ctrl+B 打开面板时排他关闭侧栏 */
  if(e.ctrlKey&&e.key==='b')document.body.classList.remove('nav-open');
});

/* 汉堡按钮 */
var _navToggleBtn=document.getElementById('nav-toggle');
if(_navToggleBtn)_navToggleBtn.addEventListener('click',function(){_navToggleDrawer();});

/* 顶栏主题按钮: 与侧栏主题按钮同步 */
var _tbTheme=document.getElementById('tb-theme');
if(_tbTheme)_tbTheme.addEventListener('click',function(){
  setTheme(getTheme()==='dark'?'light':'dark');
});

/* 顶栏面板按钮 */
var _tbPanel=document.getElementById('tb-panel');
if(_tbPanel)_tbPanel.addEventListener('click',function(){
  document.body.classList.remove('nav-open');
  togglePanel();
});

/* 顶栏设置按钮 */
var _tbSettings=document.getElementById('tb-settings');
if(_tbSettings)_tbSettings.addEventListener('click',openSettings);

/* 遮罩点击关闭 */
var _navScrim=document.getElementById('nav-scrim');
if(_navScrim)_navScrim.addEventListener('click',function(){document.body.classList.remove('nav-open');});

/* 面板按钮点击时排他关闭侧栏 */
var _btnPanel=document.getElementById('btn-panel');
if(_btnPanel)_btnPanel.addEventListener('click',function(){document.body.classList.remove('nav-open');});

/* 点击会话后关闭抽屉 */
var _sessionsEl=document.getElementById('sessions');
if(_sessionsEl)_sessionsEl.addEventListener('click',function(e){
  if(!document.body.classList.contains('nav-open'))return;
  var t=e.target;
  if(t.classList.contains('del'))return;
  _navToggleDrawer(false);
});

/* 新建会话后关闭抽屉 */
var _newbtn=document.getElementById('newbtn');
if(_newbtn)_newbtn.addEventListener('click',function(){_navToggleDrawer(false);});

var btn=document.getElementById('btn-theme');
btn.querySelector('.ico-sun').style.display=dark?'none':'block';
btn.querySelector('.ico-moon').style.display=dark?'block':'none';
/* 同步顶栏主题按钮图标 */
var _tbTheme=document.getElementById('tb-theme');
if(_tbTheme){
  _tbTheme.querySelector('.ico-sun').style.display=dark?'none':'block';
  _tbTheme.querySelector('.ico-moon').style.display=dark?'block':'none';
}
